pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        // Pre-condition: fund the contract
        uint256 deposit = 100 ether;
        address(c).call{value: deposit}("");
        uint256 balanceBefore = address(c).balance;
        // Call withdrawAll
        c.withdrawAll(recipient);
        uint256 balanceAfter = address(c).balance;
        // General rule: either the balance decreased by the full deposit (success) or stayed the same (silent failure)
        assertTrue(balanceBefore - balanceAfter == deposit || balanceBefore == balanceAfter);
    }
}

