pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _recipient, uint256 _amount) public {
        _amount = bound(_amount, 0, 5000 ether);
        vm.deal(address(c), _amount);
        uint256 balanceBefore = address(c).balance;
        // Drive a state change: ensure we have a balance to withdraw
        // Then call withdrawAll
        c.withdrawAll(_recipient);
        uint256 balanceAfter = address(c).balance;
        // General rule: if the caller is owner (address(this)), balance becomes 0; otherwise it remains the same
        if (msg.sender == c.owner()) {
            assertTrue(balanceAfter == 0);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

