pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(this));
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(attacker);
        c.withdrawAll(address(0xdead));
        uint256 balanceAfter = address(c).balance;
        // The general rule: balance can only change (decrease) if the caller is the owner
        assertTrue(balanceAfter == balanceBefore || attacker == address(this));
    }
}

