pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        // Fund the contract so the call doesn't revert due to insufficient balance
        vm.deal(address(c), amount);
        // Record the owner before the call
        address ownerBefore = c.owner();
        // Prank as the caller; if caller is not owner, the reference reverts, but we skip that case
        vm.assume(caller == ownerBefore);
        vm.prank(caller);
        c.withdrawAll(address(0x1234));
        // After a successful withdrawAll, the owner MUST remain the same
        assertTrue(c.owner() == ownerBefore);
    }
}

