pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 0, address(this).balance);
        vm.deal(address(c), amount);
        uint256 initialBalance = address(c).balance;
        uint256 beforeCallBalance = address(this).balance;
        vm.prank(caller);
        c.withdrawAll(address(0));
        bool reverted = false;
        // re-run to check revert behavior separately
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, address(0)));
        if (!success) reverted = true;
        uint256 finalBalance = address(c).balance;
        if (caller == address(this)) {
            assertTrue(!reverted, "owner should not revert");
            assertTrue(finalBalance == 0, "balance should be zero after owner withdrawAll");
        } else {
            assertTrue(reverted, "non-owner should revert");
            assertTrue(finalBalance == initialBalance, "balance unchanged for non-owner");
        }
    }
}

